def iscube(a):
    n = abs(a)
    lo, hi = 0, n
    while lo <= hi:
        mid = (lo + hi) // 2
        cub = mid * mid * mid
        if cub == n:
            return True
        elif cub < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return False
